custom_fields.health:
[[[
  const metric = variables.tank_metrics || {};
  const nutrient = states['sensor.peninsula_nutrient_balance_score'];
  const raw = Number(metric.score);
  const value = Number.isFinite(raw) ? Math.max(0, Math.min(100, raw)) : 0;
  const label = Number.isFinite(raw) ? Math.round(raw) + '%' : '—';
  const status = metric.status || 'Unavailable';
  const dash = (value * 2.513).toFixed(1);
  const color = value >= 90 ? '#67b269' : value >= 75 ? '#b7d180' : value >= 60 ? '#efd269' : value >= 40 ? '#e38b52' : '#d36571';
  const text = hass.themes?.darkMode ? '#f7fbff' : '#172033';
  const track = hass.themes?.darkMode ? '#31465b' : '#c7d6e5';
  const confidence = Number.isFinite(Number(metric.confidence)) ? Math.round(Number(metric.confidence)) + '%' : 'Unavailable';
  const concern = metric.concern || 'No active concern';
  const balance = nutrient?.attributes?.balance_status || 'Unavailable';
  const ratioRaw = Number(nutrient?.attributes?.nitrate_phosphate_ratio);
  const ratio = Number.isFinite(ratioRaw) ? Math.round(ratioRaw) + ':1' : 'Unavailable';
  const nitrate = nutrient?.attributes?.nitrate_ppm ?? '—';
  const phosphate = nutrient?.attributes?.phosphate_ppm ?? '—';

  return `
    <div style="width:100%;min-width:0;box-sizing:border-box">
      <div style="display:grid;grid-template-columns:104px minmax(0,1fr);column-gap:14px;align-items:center">
        <svg viewBox="0 0 100 100" role="img" aria-label="Tank Health ${label} ${status}" style="width:96px;height:96px;display:block">
          <circle cx="50" cy="50" r="40" fill="none" stroke="${track}" stroke-width="9"></circle>
          <circle cx="50" cy="50" r="40" fill="none" stroke="${color}" stroke-width="9" stroke-linecap="round" transform="rotate(-90 50 50)" stroke-dasharray="${dash} 251.3"></circle>
          <text x="50" y="56" text-anchor="middle" fill="${text}" font-size="20" font-weight="700">${label}</text>
        </svg>
        <div style="display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,0.75fr);gap:9px 18px;min-width:0;text-align:left;white-space:normal">
          <div style="min-width:0">
            <div style="color:var(--secondary-text-color);font-size:11px">Primary Read</div>
            <div style="font-size:12px;line-height:16px;white-space:normal;overflow-wrap:break-word;max-width:28ch">${concern}</div>
          </div>
          <div style="min-width:0">
            <div style="color:var(--secondary-text-color);font-size:11px">Nutrient Balance</div>
            <div style="font-size:12px;line-height:16px;white-space:normal">${balance}</div>
          </div>
          <div style="min-width:0">
            <div style="color:var(--secondary-text-color);font-size:11px">NO₃ : PO₄ Ratio</div>
            <div style="font-size:12px;line-height:16px;white-space:nowrap">${nitrate} : ${phosphate} ppm · ${ratio}</div>
          </div>
          <div style="min-width:0">
            <div style="color:var(--secondary-text-color);font-size:11px">Data Confidence</div>
            <div style="font-size:12px;line-height:16px">${confidence}</div>
          </div>
        </div>
      </div>
    </div>`;
]]]

variables.tank_metrics:
[[[
  const levelPoints = { desired: 100, acceptable: 80, danger: 25, sensor_data_error: 0 };
  const probes = [
    { id: 'sensor.aquarium_reefcontrol_pro_salinity_62a_temperature_level_2', weight: 15, kind: 'temperature' },
    { id: 'sensor.aquarium_reefcontrol_pro_ph_a4_level_2', weight: 15, kind: 'ph' },
    { id: 'sensor.aquarium_reefcontrol_pro_salinity_62a_level_2', weight: 10, kind: 'salinity' },
    { id: 'sensor.aquarium_reefcontrol_pro_orp_285_level_2', weight: 5, kind: 'orp' }
  ];
  let liveTotal = 0;
  let liveWeight = 0;
  let probeConfidence = 0;
  for (const probe of probes) {
    const level = states[probe.id]?.state;
    liveTotal += (levelPoints[level] ?? 0) * probe.weight;
    liveWeight += probe.weight;
    if (['desired', 'acceptable', 'danger'].includes(level)) probeConfidence += probe.weight;
  }
  const live = liveWeight ? liveTotal / liveWeight : 0;
  const chemistryState = states['sensor.peninsula_manual_chemistry_score']?.state;
  const nutrientsState = states['sensor.peninsula_nutrient_balance_score']?.state;
  const chemistry = Number(chemistryState);
  const nutrients = Number(nutrientsState);
  let weighted = live * 45;
  let total = 45;
  if (Number.isFinite(chemistry) && !['unknown', 'unavailable'].includes(chemistryState)) {
    weighted += chemistry * 25;
    total += 25;
  }
  if (Number.isFinite(nutrients) && !['unknown', 'unavailable'].includes(nutrientsState)) {
    weighted += nutrients * 25;
    total += 25;
  }
  let score = total ? weighted / total : 0;
  const level = Object.fromEntries(probes.map(p => [p.kind, states[p.id]?.state]));
  const leakBad = states['binary_sensor.rscontrolpro_415492340_leak_detector']?.state === 'off';
  const reefcontrolDanger = ['temperature', 'ph', 'salinity'].some(k => level[k] === 'danger');
  const orpDanger = level.orp === 'danger';
  const nitrate = Number(states['input_number.peninsula_nitrate_no3_ppm']?.state);
  const phosphate = Number(states['input_number.peninsula_phosphate_po4_ppm']?.state);
  const nitrateHigh = Number.isFinite(nitrate) && nitrate > 30;
  const phosphateHigh = Number.isFinite(phosphate) && phosphate > 2;
  if (leakBad) score = Math.min(score, 39);
  else if (reefcontrolDanger || nitrateHigh || phosphateHigh) score = Math.min(score, 59);
  else if (orpDanger) score = Math.min(score, 74);
  score = Math.round(score);

  const freshInputs = [
    { id: 'input_number.peninsula_alkalinity_dkh', weight: 12, days: 8 },
    { id: 'input_number.peninsula_calcium_ca_ppm', weight: 8, days: 17 },
    { id: 'input_number.peninsula_magnesium_mg_ppm', weight: 5, days: 35 },
    { id: 'input_number.peninsula_nitrate_no3_ppm', weight: 8, days: 8 },
    { id: 'input_number.peninsula_phosphate_po4_ppm', weight: 8, days: 8 }
  ];
  let confidenceTotal = probeConfidence * 100;
  let confidenceWeight = liveWeight;
  const now = Date.now();
  for (const input of freshInputs) {
    const changed = Date.parse(states[input.id]?.last_changed || '');
    const age = Number.isFinite(changed) ? (now - changed) / 86400000 : input.days * 2;
    const freshness = age <= input.days ? 100 : age >= input.days * 2 ? 0 : ((input.days * 2 - age) / input.days * 100);
    confidenceTotal += freshness * input.weight;
    confidenceWeight += input.weight;
  }
  const confidence = confidenceWeight ? Math.round(confidenceTotal / confidenceWeight) : 0;
  const nutrient = states['sensor.peninsula_nutrient_balance_score'];
  const cautionAttr = nutrient?.attributes?.caution;
  const nutrientCaution = cautionAttr === true || String(cautionAttr).toLowerCase() === 'true';
  let status;
  if (leakBad || score < 40) status = 'Critical';
  else if (reefcontrolDanger || score < 60) status = 'Attention';
  else if (orpDanger || nutrientCaution) status = 'Caution';
  else if (score < 75) status = 'Watch';
  else if (score < 90) status = 'Healthy';
  else status = 'Excellent';

  const balance = String(nutrient?.attributes?.balance_status || '').trim();
  let concern = 'No active concern';
  if (leakBad) concern = 'Leak detector reports a leak';
  else if (level.temperature === 'danger') concern = 'Temperature needs attention';
  else if (level.ph === 'danger') concern = 'pH needs attention';
  else if (level.orp === 'danger') concern = 'ORP needs attention';
  else if (level.salinity === 'danger') concern = 'Salinity needs attention';
  else if (balance === 'Imbalanced') concern = 'Nitrate and phosphate are imbalanced';
  else if (nutrientCaution) concern = 'Nutrients are balanced but elevated';

  return { score, status, confidence, concern, live: Math.round(live) };
]]]

