custom_fields.summary:
[[[
    const t = Number(states['sensor.aquarium_rsmat_500_total_usage']?.state);
    const r = Number(states['sensor.aquarium_rsmat_500_remaining_length']?.state);
    const unit = states['sensor.aquarium_rsmat_500_total_usage']?.attributes?.unit_of_measurement || '';
    if (!Number.isFinite(t)) return 'Usage unavailable';
    const totalRoll = Number.isFinite(r) ? t + r : NaN;
    return '<span style="font-size:12px;color:var(--secondary-text-color)">Total use</span><br>' +
      '<span style="font-size:22px;font-weight:750;color:var(--primary-text-color)">' + t.toFixed(1) + '</span>' +
      '<span style="font-size:11px;color:var(--secondary-text-color)"> ' + unit +
      (Number.isFinite(totalRoll) ? ' / ' + totalRoll.toFixed(1) + ' ' + unit : '') + '</span>';
  ]]]

custom_fields.progress:
[[[
    const t = Number(states['sensor.aquarium_rsmat_500_total_usage']?.state);
    const r = Number(states['sensor.aquarium_rsmat_500_remaining_length']?.state);
    const pct = Number.isFinite(t) && Number.isFinite(r) && t + r > 0 ? Math.max(0, Math.min(100, t / (t + r) * 100)) : 0;
    return '<div style="height:10px;border-radius:999px;background:' +
      (hass.themes?.darkMode ? '#344258' : '#cad6e3') + ';overflow:hidden">' +
      '<div style="height:100%;width:' + pct.toFixed(1) + '%;background:linear-gradient(90deg,#d95bea,#b94fe5);"></div></div>';
  ]]]

custom_fields.stats:
[[[
    const today = Number(states['sensor.aquarium_rsmat_500_today_usage']?.state);
    const avg = Number(states['sensor.aquarium_rsmat_500_daily_average_usage']?.state);
    const days = Number(states['sensor.aquarium_rsmat_500_days_till_end_of_roll']?.state);
    const unit = states['sensor.aquarium_rsmat_500_today_usage']?.attributes?.unit_of_measurement || '';
    const chip = (v) => '<span style="display:inline-block;padding:5px 9px;margin:2px 3px 0 0;border:1px solid var(--divider-color);border-radius:10px;font-size:10px;color:var(--primary-text-color)">' + v + '</span>';
    return chip((Number.isFinite(today) ? today.toFixed(1) : '—') + ' ' + unit + ' today') +
      chip((Number.isFinite(avg) ? avg.toFixed(1) : '—') + ' daily avg') +
      chip((Number.isFinite(days) ? Math.round(days) : '—') + ' days left');
  ]]]

